def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    """Calculate delivery fees for each area based on distance in km."""
    fees = {}
    for area, km in areas_km.items():
        # Base fee for delivery within 1km, increases by 100 shillings per additional km
        if km <= 1.0:
            fees[area] = 100
        elif km <= 2.0:
            fees[area] = 200
        elif km <= 5.0:
            fees[area] = 500
        else:
            # For distances beyond 5km, charge 500 shillings plus 100 per additional km
            fees[area] = 500 + 100 * (km - 5.0)
    return fees
