def fee_labels(distances_m: list[int]) -> list[str]:
    """Return delivery fee labels for each distance in metres."""
    fees = []
    for dist in distances_m:
        # Base fee for 0-100m, then increases in increments
        if dist <= 100:
            fee = 100
        elif dist <= 200:
            fee = 150
        elif dist <= 500:
            fee = 200
        else:
            fee = 250 + (dist - 500) // 50
        # Format as KES X,XXX
        fee_str = f"KES {fee:,}"
        fees.append(fee_str)
    return fees
